import express from 'express';
import { router } from './routes/index.js';

export const app = express();
app.use(router);

import { bookSlot } from '../services/booking-service.js';

export function createBooking(req: { body: unknown }) {
  return bookSlot(req.body);
}

import { findUser } from '../services/user-service.js';

export function getUser(req: { params: { id: string } }) {
  return findUser(req.params.id);
}

import { db } from '../db.js';

export class Booking {
  constructor(readonly input: unknown) {
    db.rows.push(input);
  }
}

export class User {
  constructor(readonly id: string) {}
}

import { Router } from 'express';
import { createBooking } from '../controllers/booking-controller.js';
import { getUser } from '../controllers/user-controller.js';

export const router = Router();
router.post('/bookings', createBooking);
router.get('/users/:id', getUser);

import { Booking } from '../models/booking.js';

export function bookSlot(input: unknown) {
  return new Booking(input);
}

import { db } from '../db.js';

export function findUser(id: string) {
  return db.rows.find((r) => r === id);
}

